from random import choice
import json, os
import pygame
def clean_word(word):
    """
    clean_word : function: clean the word and remplace all accents
    Args:
        word : str : the word to clean
    
    Returns:
        new_word : str : word cleaned
    """
    resultat = word
    resultat = resultat.lower()
    resultat = resultat.replace('é', "e")
    resultat = resultat.replace('ê', "e")
    resultat = resultat.replace('è', "e")
    resultat = resultat.replace('ë', "e")
    resultat = resultat.replace('à', "a")
    resultat = resultat.replace('ù', "u")
    resultat = resultat.replace('ü', "e")
    resultat = resultat.replace('î', "i")
    resultat = resultat.replace('ï', "i")
    resultat = resultat.replace('ä', "a")
    resultat = resultat.replace('ö', "o")
    resultat = resultat.replace('ô', "o")
    resultat = resultat.upper()
    resultat = resultat.strip()
    return resultat


def init_word_to_find(dictionnary_file):
    """
    init_word_to_find : function : retrieve a random word in the file given in parameters

    Args:
        dictionnary_file : str : dictionnary file in which we need to find a random word
    """

    """
    give_new_letter : function : ask for a new letter and check if not already in given letters

    Args:
        letter_list : list[str] : list of the already given letters
    """
    file = open(dictionnary_file, "r")
    content = file.read()
    content_split = content.split("\n")
    file.close()
    result = choice(content_split)
    return result

def display_word(word_to_find, letter_list):
    """
    display_word : display the word_to_find regarding the letter_list

    Args:
        word_to_find : str : word to display ( - for unknown letters )
        letter_list : list[str] : list of the already given letters
    """
    # TODO
    # Using print("", end="") to display letter by letter in the same line
    word_final = ""
    for letter in word_to_find:
        if letter in letter_list:
            word_final += letter
        else:
            word_final += "_"
    return word_final


def game_loop(random_word):
    """
    game_loop : function : run the main game loop
    
    Args:
        random_word : str : the word that the player will need to find !
    """ 
    max_tries = 11
    current_tries = 0
    given_letters = []
    given_letter = ""

    alphabet_letters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

