def save_game(file_name, content):
    with open(file_name, "w") as file:
        json.dump(content, file)

def load_game(file_name):
    try:
        with open(file_name, "r") as file:
            return json.load(file)
    except:
        return []

def high_score(saved_games):
    # res = saved_games[0]
    res = {"player_name": "", "word": "", "remaining_tries": -1}
    for game in saved_games:
        if res.get("remaining_tries") < game.get("remaining_tries"):
            res = game
    return res

def high_score_with_lambda(saved_games):
    sorted_games = sorted(saved_games, key=lambda x:x['remaining_tries'])
    return sorted_games[-1]

